package sesion3;

public class calculadora {

	public static Integer suma(int i, int j) {
		// TODO Auto-generated method stub
		return i+j;
	}

	public static Integer resta(int i, int j) {
		// TODO Auto-generated method stub
		return i-j;
	}

	public static Integer multiplicacion(int i, int j) {
		// TODO Auto-generated method stub
		return i*j;
	}

	public static Integer division(int i, int j) {
		
		return i/j;
	}

}
